      lastColor: PALETTE.some(([color]) => color === saved.lastColor) ? saved.lastColor : 'yellow',
      readingLineHeight: ['1.5', '1.75', '2'].includes(saved.readingLineHeight) ? saved.readingLineHeight : '',
