      const menu = new Menu();
      menu.addItem(item => item.setTitle('打开标注侧栏').setIcon('list').onClick(() => this.showAnnotations()));
      menu.addItem(item => item.setTitle('导出当前笔记摘录').setIcon('file-output').onClick(() => run(() => this.exportAnnotations())));
